import { cn } from "@/lib/utils";
import { TrendingUp, ArrowUpRight } from "lucide-react";

interface Card03Props {
  title?: string;
  value?: string;
  change?: number;
  period?: string;
}

export default function Card_05({
  title = "Total Revenue",
  value = "$45,231.89",
  change = 12.5,
  period = "from last month",
}: Card03Props) {
  return (
    <div
      className={cn(
        "group w-full max-w-sm",
        "rounded-2xl border border-white/[0.08]",
        "bg-white/[0.025] backdrop-blur-xl",
        "p-5",
        "transition-all duration-300",
        "hover:-translate-y-0.5 hover:border-white/[0.14]",
        "hover:bg-white/[0.035]",
      )}
    >
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <p className="text-[11px] font-medium uppercase tracking-[0.12em] text-zinc-500">
            {title}
          </p>

          <h3 className="mt-3 truncate text-3xl font-medium tracking-tight text-white">
            {value}
          </h3>
        </div>

        <div
          className={cn(
            "flex size-10 shrink-0 items-center justify-center",
            "rounded-xl border border-violet-400/15",
            "bg-violet-500/[0.07]",
            "transition-all duration-300",
            "group-hover:border-violet-400/25",
            "group-hover:bg-violet-500/[0.10]",
          )}
        >
          <TrendingUp className="size-4 text-violet-300" />
        </div>
      </div>

      <div className="mt-6 flex items-center gap-2 border-t border-white/[0.06] pt-4">
        <div className="flex items-center gap-1 rounded-full bg-violet-500/[0.07] px-2 py-1 text-xs font-medium text-violet-300">
          <ArrowUpRight className="size-3.5" />
          <span>{change}%</span>
        </div>

        <span className="text-xs text-zinc-500">{period}</span>
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";
import { Star, Quote } from "lucide-react";

interface Card04Props {
  author?: string;
  role?: string;
  text?: string;
  rating?: number;
  avatar?: string;
}

export default function Card_06({
  author = "Marcus Johnson",
  role = "CEO at TechCorp",
  text = "This product has transformed how we approach our workflow. Highly recommended for any team.",
  rating = 5,
  avatar = "https://api.dicebear.com/7.x/avataaars/svg?seed=Marcus",
}: Card04Props) {
  return (
    <div
      className={cn(
        "group relative w-full max-w-sm overflow-hidden",
        "rounded-2xl border border-white/[0.08]",
        "bg-white/[0.025] backdrop-blur-xl",
        "p-6",
        "transition-all duration-300",
        "hover:-translate-y-1 hover:border-white/[0.14]",
        "hover:bg-white/[0.035]",
      )}
    >
      <div className="absolute right-5 top-5 flex size-8 items-center justify-center rounded-full border border-white/[0.06] bg-white/[0.025]">
        <Quote className="size-3.5 text-violet-400" />
      </div>

      <div className="flex items-center gap-1">
        {Array.from({ length: rating }).map((_, i) => (
          <Star
            key={i}
            className="size-3.5 fill-violet-400 text-violet-400"
          />
        ))}
      </div>

      <p className="mt-5 text-sm leading-6 text-zinc-300">
        “{text}”
      </p>

      <div className="mt-6 flex items-center gap-3 border-t border-white/[0.06] pt-5">
        <img
          src={avatar}
          alt={author}
          className="size-9 rounded-full border border-white/[0.08] object-cover"
        />

        <div className="min-w-0">
          <p className="truncate text-sm font-medium text-zinc-200">
            {author}
          </p>
          <p className="mt-0.5 truncate text-xs text-zinc-500">{role}</p>
        </div>
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";
import { Package, ShoppingCart, ArrowUpRight } from "lucide-react";

interface Card05Props {
  name?: string;
  category?: string;
  price?: string;
  image?: string;
  inStock?: boolean;
}

export default function Card_07({
  name = "Premium Wireless Headphones",
  category = "Electronics",
  price = "$199.99",
  image = "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=400&h=400&fit=crop",
  inStock = true,
}: Card05Props) {
  return (
    <div
      className={cn(
        "group w-full max-w-sm overflow-hidden",
        "rounded-2xl border border-white/[0.08]",
        "bg-white/[0.025] backdrop-blur-xl",
        "transition-all duration-300",
        "hover:-translate-y-1 hover:border-white/[0.14]",
        "hover:bg-white/[0.035]",
        "shadow-[0_12px_40px_rgba(0,0,0,0.15)]",
      )}
    >
      <div className="relative h-52 overflow-hidden bg-[#0c0c0f]">
        <img
          src={image}
          alt={name}
          className="size-full object-cover transition-transform duration-500 group-hover:scale-[1.04]"
        />

        <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent" />

        {inStock && (
          <div
            className={cn(
              "absolute left-4 top-4",
              "rounded-full border border-violet-400/20",
              "bg-[#09090b]/75 px-2.5 py-1",
              "text-[10px] font-medium uppercase tracking-[0.12em]",
              "text-violet-300 backdrop-blur-xl",
            )}
          >
            In stock
          </div>
        )}

        <div className="absolute bottom-4 right-4 flex size-8 items-center justify-center rounded-full border border-white/10 bg-black/40 backdrop-blur-xl">
          <ArrowUpRight className="size-3.5 text-zinc-200" />
        </div>
      </div>

      <div className="p-5">
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <p className="text-[10px] font-medium uppercase tracking-[0.12em] text-zinc-500">
              {category}
            </p>

            <h3 className="mt-2 truncate text-sm font-medium text-zinc-100">
              {name}
            </h3>
          </div>

          <Package className="mt-0.5 size-4 shrink-0 text-zinc-600" />
        </div>

        <div className="mt-5 flex items-center justify-between border-t border-white/[0.06] pt-4">
          <p className="text-lg font-medium tracking-tight text-white">
            {price}
          </p>

          <button
            type="button"
            aria-label="Add to cart"
            className={cn(
              "flex size-9 items-center justify-center rounded-full",
              "border border-white/[0.08]",
              "bg-white/[0.04] text-zinc-400",
              "transition-all duration-200",
              "hover:border-violet-400/25 hover:bg-violet-500/[0.08]",
              "hover:text-violet-300",
              "focus:outline-none focus:ring-2 focus:ring-violet-400/20",
            )}
          >
            <ShoppingCart className="size-4" />
          </button>
        </div>
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";
import { Code2, GitBranch, Star, ArrowUpRight } from "lucide-react";

interface Card06Props {
  name?: string;
  description?: string;
  language?: string;
  stars?: number;
  url?: string;
}

export default function Card_08({
  name = "React Query",
  description = "Powerful asynchronous state management library for data fetching and caching.",
  language = "TypeScript",
  stars = 42100,
  url = "github.com/example/repo",
}: Card06Props) {
  return (
    <div
      className={cn(
        "group w-full max-w-sm",
        "rounded-2xl border border-white/[0.08]",
        "bg-[#09090b]",
        "p-5",
        "transition-all duration-300",
        "hover:-translate-y-1 hover:border-violet-400/20",
        "hover:bg-white/[0.025]",
      )}
    >
      <div className="flex items-start justify-between">
        <div
          className={cn(
            "flex size-10 items-center justify-center rounded-xl",
            "border border-violet-400/15",
            "bg-violet-500/[0.07]",
          )}
        >
          <Code2 className="size-4 text-violet-300" />
        </div>

        <a
          href={`https://${url}`}
          target="_blank"
          rel="noreferrer"
          aria-label="Open repository"
          className={cn(
            "flex size-8 items-center justify-center rounded-full",
            "text-zinc-600 transition-all duration-200",
            "hover:bg-white/[0.05] hover:text-zinc-200",
          )}
        >
          <ArrowUpRight className="size-4" />
        </a>
      </div>

      <div className="mt-5">
        <h3 className="text-sm font-medium text-zinc-100">{name}</h3>

        <p className="mt-2 line-clamp-2 text-xs leading-5 text-zinc-500">
          {description}
        </p>
      </div>

      <div className="mt-6 flex items-center justify-between border-t border-white/[0.06] pt-4">
        <div className="flex items-center gap-2">
          <span className="size-2 rounded-full bg-violet-400" />
          <span className="text-xs text-zinc-400">{language}</span>
        </div>

        <div className="flex items-center gap-1.5 text-xs text-zinc-500">
          <Star className="size-3.5 text-zinc-500" />
          <span>{stars.toLocaleString()}</span>
        </div>

        <GitBranch className="size-3.5 text-zinc-600" />
      </div>
    </div>
  );
}

import { cn } from "@/lib/utils";
import { Users, Plus, ArrowUpRight } from "lucide-react";

interface Card07Props {
  teamName?: string;
  members?: number;
  maxMembers?: number;
  avatars?: string[];
}

export default function Card_09({
  teamName = "Design Team",
  members = 5,
  maxMembers = 10,
  avatars = [
